from pathlib import Path
import json,hashlib
home=Path.home()
ids={'repair':'DEV-PRED-A2Z-REVIEW-CALL-REPAIR-20261005-E042','resume':'DEV-PRED-A2Z-RESUME-EVIDENCE-20261005-E043'}
def read(p):
    if p.is_symlink() or not p.is_file():
        return {}
    try:
        v=json.loads(p.read_text())
        return v if isinstance(v,dict) else {}
    except (ValueError,OSError):
        return {}
report={'states':{},'events':[],'source_modified':False,'experiment_executed':False}
for label,tid in ids.items():
    report['states'][label]=read(home/'.local/state/prediction-project-executor'/(tid+'.json'))
prior=read(home/'.local/share/prediction-project-executor/worktrees'/ids['resume']/'diagnostic-result/resume-evidence.json')
report['prior']=prior
base=home/'.local/share/prediction-chat-bridge'
for folder in ('sent','inflight','outbox','failed'):
    directory=base/folder
    if not directory.is_dir():
        continue
    for p in sorted(directory.glob('*.json'),reverse=True)[:3000]:
        if p.is_symlink() or not p.is_file() or p.stat().st_size>2000000:
            continue
        value=read(p)
        raw=json.dumps(value,ensure_ascii=False)
        label=next((k for k,v in ids.items() if v in raw),None)
        if label is None:
            continue
        texts=[]
        def collect(v):
            if isinstance(v,str):
                texts.extend(v.splitlines())
            elif isinstance(v,dict):
                for k,x in v.items():
                    if k in ('message','payload','result','detail','error','stdout','stderr','body','text'):
                        collect(x)
        collect(value)
        errors=[x.strip()[:900] for x in texts if any(t in x for t in ('PermissionError','ERROR=','TaskError','blocked','Traceback','Error:','A2Z_RESUME'))]
        report['events'].append({'task':label,'event_file':p.name,'errors':errors[-8:]})
models=read(home/'.codex/models_cache.json').get('models',[])
visible=[{'slug':m.get('slug'),'display_name':m.get('display_name')} for m in models if isinstance(m,dict) and m.get('visibility')=='list']
report['visible_models']=visible
repair_root=home/'.local/share/prediction-project-executor/worktrees'/ids['repair']
target=repair_root/'control/hourly/full_chain_qualification.py'
report['repair_source_sha256']=hashlib.sha256(target.read_bytes()).hexdigest() if target.is_file() and not target.is_symlink() else None
messages=' '.join(e for row in report['events'] for e in row['errors'])
messages+=' '+json.dumps(prior.get('repair_events',[]))
reason='SHARED_COORDINATOR_OUTSIDE_SCOPE' if 'blocked write outside task roots' in messages else 'READ_EXACT_REPAIR_ERRORS'
if not report['events'] and not prior:
    reason='REPAIR_EVIDENCE_UNAVAILABLE'
sol=[m for m in visible if str(m['display_name']).strip().casefold()=='gpt-5.6 sol']
astra=[m for m in visible if str(m['display_name']).strip().casefold()=='gpt-6 astra']
report['reason']=reason
out=Path.cwd()/'diagnostic-result'
out.mkdir(exist_ok=True)
(out/'repair-blocker.json').write_text(json.dumps(report,indent=2))
detail=next((e[-120:] for row in reversed(report['events']) for e in reversed(row['errors']) if 'Error' in e or 'ERROR=' in e),'NO_ERROR_LINE')
print('REPAIR_BLOCKER '+json.dumps({'reason':reason,'sol':len(sol),'astra':len(astra),'patched':report['repair_source_sha256']=='d8fc774c936c92e4e5bc65cd600f7106774f3233b0e0f5555e02e2223962198e','detail':detail},separators=(',',':')),flush=True)
raise SystemExit(0 if report['events'] or prior else 1)
